typedef int SSEventId;
enum EventType { SS_FE_ONX = 28 };

class entity;
class FEMenu
{
public:
	void setBack(FEMenu *, int = 1);
};

class SoundScriptManager
{
public:
	static SoundScriptManager *inst();
	SSEventId playEvent(EventType, entity * = 0, float = 0);
};

class FEEntityManager
{
	bool cam_stopped;

public:
	enum {
		CAM_POS_WALL_1,
		CAM_POS_WALL_2_IN,
		CAM_POS_WALL_2_OUT
	};

	void JumpTo(int);
	void BioTBZoom(bool);
	bool CamIsMoving() { return !cam_stopped; }
	void SurferSelected() {}
};

class FEManager
{
public:
	FEEntityManager *em;
	int current_surfer;
};

class SurferBioFrontEnd : public FEMenu {};
class AccompFrontEnd : public FEMenu {};

class GraphicalMenuSystem
{
public:
	enum {
		TrickBookMenu = 3,
		AccompMenu = 5
	};

	FEMenu *menus[16];
	void MakeActive(int);
};

void assert(int);

class SurferFrontEnd : public FEMenu
{
	enum {
		OnSurfer,
		BioHigh,
		TrickHigh,
		PersHigh,
		ScrapHigh,
		ContHigh,
		HCapHigh
	};

	int state;
	GraphicalMenuSystem *sys;
	FEManager *manager;
	SurferBioFrontEnd *bio_menu;
	bool in_tb_or_bio;

public:
	int current_surfer_index;
	static bool personality_up;

	void MakeActive(FEMenu *);
	void Pick(int);
	void SetPersonality(bool);
	void Select(int entry_index);
};

void SurferFrontEnd::Select(int entry_index)
{
	SoundScriptManager::inst()->playEvent(SS_FE_ONX);

	if(state == BioHigh || state == TrickHigh || state == ScrapHigh) in_tb_or_bio = true;

	switch(state)
	{
	case OnSurfer:
		if(manager->em->CamIsMoving())
			manager->em->JumpTo(FEEntityManager::CAM_POS_WALL_2_IN);
		else
		{
			manager->current_surfer = current_surfer_index;
			manager->em->SurferSelected();
			Pick(current_surfer_index);
		}
		break;
	case BioHigh:
		MakeActive(bio_menu);
		if(manager->em->CamIsMoving())
			manager->em->JumpTo(FEEntityManager::CAM_POS_WALL_2_OUT);
		else manager->em->BioTBZoom(true);
		break;
	case TrickHigh:
		sys->MakeActive(GraphicalMenuSystem::TrickBookMenu);
		if(manager->em->CamIsMoving())
			manager->em->JumpTo(FEEntityManager::CAM_POS_WALL_2_OUT);
		else manager->em->BioTBZoom(true);
		break;
	case PersHigh:
		if(manager->em->CamIsMoving())
			manager->em->JumpTo(FEEntityManager::CAM_POS_WALL_2_IN);
		SetPersonality(!personality_up);
		break;
	case ScrapHigh:
		((AccompFrontEnd*)sys->menus[GraphicalMenuSystem::AccompMenu])->setBack(this);
		sys->MakeActive(GraphicalMenuSystem::AccompMenu);
		if(manager->em->CamIsMoving())
			manager->em->JumpTo(FEEntityManager::CAM_POS_WALL_2_OUT);
		else manager->em->BioTBZoom(true);
		break;
	case ContHigh:
		if(manager->em->CamIsMoving())
			manager->em->JumpTo(FEEntityManager::CAM_POS_WALL_2_IN);
		else
		{
			manager->current_surfer = current_surfer_index;
			manager->em->SurferSelected();
			Pick(current_surfer_index);
		}
		break;
	case HCapHigh: break;	// do nothing
	default: assert(0);
	}
}
